from common import add, case

# Niveau 1 : expressions, contrôle, données et bibliothèque standard.
add(1,'variables','integer_division',lambda n:case(f'int a={n+7}, b=3; printf("%d", a/b);',(n+7)//3,'La division entre deux int tronque la partie fractionnaire ; aucun flottant n’intervient.','Les opérandes sont entiers|Le résultat de / est un int|Le reste se calcule avec %','/ produit ici un double|La division arrondit au plus proche|Le diviseur est nul'))
add(1,'variables','negative_remainder',lambda n:case(f'printf("%d", -{n+5} % 4);',-((n+5)%4),'En C17, la division entière tronque vers zéro. Un reste non nul a le signe du dividende.','Le dividende est négatif|Le diviseur est positif|Le reste a une valeur absolue inférieure à 4','Le reste est toujours positif|% effectue une division flottante|Le diviseur est négatif'))
add(1,'control_flow','short_circuit_and',lambda n:case(f'int x={n}; int r=0 && ++x; printf("%d %d",r,x);',f'0 {n}','L’opérande gauche de && étant faux, ++x n’est pas évalué.','&& court-circuite son opérande droit|x n’est pas incrémenté|Le résultat logique est un int','++x est toujours évalué|&& est un ET bit à bit|Le résultat dépend de l’optimisation',wrong=[f'0 {n+1}',f'1 {n+1}','Comportement indéfini']))
add(1,'control_flow','short_circuit_or',lambda n:case(f'int x={n}; int r=1 || ++x; printf("%d %d",r,x);',f'1 {n}','Un opérande gauche vrai suffit à ||. L’incrément à droite est ignoré.','Le OU logique court-circuite|L’opérande droit est ignoré|Le résultat logique vaut vrai','x est incrémenté|Les deux opérandes sont obligatoirement évalués|Le OU logique est un OU bit à bit',wrong=[f'1 {n+1}',f'0 {n}','Comportement indéfini']))
add(1,'loops','continue_filter',lambda n:case(f'int s=0; for(int i=1;i<={n+3};i++){{if(i%2==0)continue;s+=i;}} printf("%d",s);',sum(i for i in range(1,n+4) if i%2),'continue passe à l’itération suivante ; seuls les indices impairs sont additionnés.','Les indices pairs sont ignorés|La borne supérieure est incluse|continue ne termine pas toute la boucle','Les indices impairs sont ignorés|continue agit comme break|Le dernier indice est exclu'))
add(1,'loops','do_while_once',lambda n:case(f'int x={n+4}; do{{x-=2;}}while(x<0); printf("%d",x);',n+2,'Le corps d’un do while s’exécute avant le premier contrôle de sa condition.','Le corps s’exécute au moins une fois|La condition est contrôlée après le corps|x reste positif','La condition est contrôlée avant le corps|Le corps ne s’exécute pas|La boucle est infinie'))
add(1,'functions','pass_by_value',lambda n:case(f'int x={n+2}; inc(x); printf("%d",x);',n+2,'Le paramètre de inc est une copie ; son incrément ne modifie pas l’appelant.','Le paramètre reçoit une copie|La variable de main reste inchangée|La fonction ne reçoit pas d’adresse','C passe automatiquement x par référence|Le paramètre est un alias de x|La fonction renvoie la nouvelle valeur',preamble='static void inc(int x){++x;}'))
add(1,'pointers','write_through_pointer',lambda n:case(f'int x={n}; int *p=&x; *p+=3; printf("%d",x);',n+3,'p contient l’adresse de x ; *p désigne directement cet objet.','p pointe vers x|*p est une lvalue modifiable|L’écriture affecte x','p contient une copie de la valeur de x|L’écriture alloue un nouvel int|p doit être libéré avec free'))
add(1,'arrays','zero_initialization',lambda n:case(f'int a[5]={{{n}, {n+1}}}; printf("%d %d",a[1],a[4]);',f'{n+1} 0','Une initialisation partielle met à zéro les autres éléments du tableau.','Le tableau a cinq éléments|Les éléments omis sont initialisés à zéro|Le dernier indice valide est 4','a[4] est indéterminé|Le tableau a deux éléments|Le dernier indice valide est 5',wrong=[f'{n+1} {n}',f'{n} 0','Comportement indéfini']))
add(1,'strings','strlen_vs_sizeof',lambda n:case(f'char s[]="{("a"*(n+1))}"; printf("%zu %zu",strlen(s),sizeof s);',f'{n+1} {n+2}','strlen ignore le terminateur nul ; sizeof inclut tout le tableau, terminateur compris.','s est un tableau de char|Un terminateur nul est ajouté|sizeof s mesure le tableau entier','strlen compte le terminateur|sizeof s mesure un pointeur|Le tableau ne contient aucun nul',wrong=[f'{n+2} {n+2}',f'{n+1} {n+1}','Erreur de compilation']))
add(1,'structures','copy_struct',lambda n:case(f'struct P{{int x;}}; struct P a={{{n}}}; struct P b=a; b.x+=2; printf("%d %d",a.x,b.x);',f'{n} {n+2}','L’affectation copie les membres de la structure ; les deux membres x sont indépendants.','b est un objet distinct|Le membre x est copié|Modifier b.x ne modifie pas a.x','b est une référence vers a|Les deux x partagent leur stockage|L’affectation de structures est interdite',wrong=[f'{n+2} {n+2}',f'{n} {n}','Erreur de compilation']))
add(1,'enum','enum_values',lambda n:case(f'enum E{{A={n},B,C}}; printf("%d",C);',n+2,'Après un énumérateur explicitement initialisé, les suivants augmentent de un.','A est explicitement initialisé|B suit A de un|Les constantes d’énumération ont ici le type int','Tous les énumérateurs valent zéro|C vaut automatiquement deux|Une enum alloue de la mémoire dynamique'))
add(1,'logic','bit_mask',lambda n:case(f'unsigned x={n+8}u; printf("%u",x & 3u);',(n+8)&3,'Le masque 3 conserve les deux bits de poids faible.','& est un opérateur bit à bit|Les opérandes sont non signés|Le masque ne conserve que deux bits','& court-circuite|Le masque conserve les bits de poids fort|L’opérateur modifie x'))
add(1,'variables','char_size',lambda n:case(f'char data[{n+3}]; printf("%zu",sizeof data);',n+3,'sizeof(char) vaut toujours un en C ; un octet C ne signifie pas nécessairement huit bits.','sizeof(char) vaut 1|sizeof data porte sur le tableau|Aucun élément n’est lu','Un char fait toujours huit octets|sizeof lit les valeurs non initialisées|Le tableau doit être libéré'))
add(1,'functions','static_counter',lambda n:case(f'int a=tick(); int b=tick(); printf("%d %d",a,b);',f'{n+1} {n+2}','La variable locale static conserve sa valeur entre les appels. Les appels sont séquencés.','La variable static persiste entre appels|Son initialisation n’a lieu qu’une fois|Les appels sont effectués dans deux instructions','La variable est réinitialisée à chaque appel|Les deux appels sont non séquencés|Une variable static locale est sur le tas',preamble=f'static int tick(void){{static int x={n};return ++x;}}',wrong=[f'{n+1} {n+1}',f'{n} {n+1}','Comportement indéfini']))
add(1,'control_flow','switch_fallthrough',lambda n:case(f'int x=0; switch({n%2}){{case 0:x+=2;case 1:x+=3;break;default:x=9;}} printf("%d",x);',3 if n%2 else 5,'Sans break après case 0, l’exécution continue dans case 1.','Un case n’introduit pas de sortie implicite|break quitte le switch|default n’est pas exécuté ici','Chaque case se termine implicitement|break quitte main|default est toujours exécuté'))
add(1,'strings','strcmp_sign',lambda n:case('int r=strcmp("abc","abd"); printf("%d",r<0);',1,'strcmp garantit le signe de la différence lexicographique, pas une valeur numérique précise.','Le test porte sur le signe de strcmp|Les chaînes sont terminées par zéro|abc précède abd lexicographiquement','strcmp garantit exactement -1|strcmp compare les adresses|strcmp modifie les chaînes'))
add(1,'memory','calloc_zero',lambda n:case(f'int *p=calloc({n+1},sizeof *p); if(!p)return 1; printf("%d",p[{n}]); free(p);',0,'calloc met à zéro les bits du bloc ; pour int, cela représente zéro.','L’échec d’allocation est contrôlé|L’indice est dans les bornes|Le bloc est libéré une fois','calloc laisse ces int indéterminés|L’indice est hors limites|free doit être appelé sur chaque élément'))
add(1,'arrays','pointer_step',lambda n:case(f'int a[]={{2,{n+3},9}}; int *p=a; ++p; printf("%d",*p);',n+3,'Ajouter un à un int* avance d’un élément int, pas d’un octet.','p pointe d’abord sur a[0]|Après ++p, p pointe sur a[1]|Le tableau reste valide','++p incrémente a[0]|p avance nécessairement d’un octet|Le pointeur doit être libéré'))
add(1,'control_flow','conditional_operator',lambda n:case(f'int a={n},b={n+3}; printf("%d",a>b?a:b);',n+3,'L’opérateur conditionnel n’évalue que l’une de ses deux branches.','a>b est faux|La branche b est choisie|Une seule des deux branches est évaluée','Les deux branches sont toujours évaluées|a est supérieur à b|?: modifie automatiquement a'))

# Niveau 2 : contrats, conversions, alias et ressources.
add(2,'arrays','sizeof_array_parameter',lambda n:case(f'int a[{n+3}]; printf("%d",isptr(a));',1,'Un paramètre déclaré int a[10] est ajusté en int*. sizeof a est donc sizeof(int*).','Le paramètre est ajusté en pointeur|La taille n’est pas transmise automatiquement|Le tableau de main reste un tableau','Le paramètre copie dix int|sizeof a donne la longueur passée|La borne écrite impose une vérification dynamique',preamble='static int isptr(int a[10]){return sizeof a==sizeof(int*);}'))
add(2,'const','const_pointee',lambda n:case(f'int x={n}; const int *p=&x; *p=7;','Erreur de compilation','L’objet peut être modifié via x, mais l’expression *p est qualifiée const.','p peut changer d’adresse|*p n’est pas modifiable via p|x lui-même n’est pas const','p est un pointeur constant|x est devenu const|L’écriture compile puis provoque un segfault',mode='compile_fail'))
add(2,'const','const_pointer',lambda n:case(f'int x={n}; int *const p=&x; *p+=2; printf("%d",x);',n+2,'La qualification const porte sur p, pas sur l’int désigné.','p ne peut pas être réaffecté|L’int pointé reste modifiable|p désigne x','L’int pointé est const|p peut être réaffecté|Le mot const est ignoré'))
add(2,'memory','realloc_safe_pattern',lambda n:case(f'size_t cap={n+2}; int *p=malloc(cap*sizeof *p); if(!p)return 1; int *tmp=realloc(p,(cap+2)*sizeof *p); if(tmp)p=tmp; free(p);','Le pointeur initial reste libérable si realloc échoue.','Sur échec, realloc renvoie NULL et laisse l’ancien bloc intact ; le temporaire évite de perdre son adresse.','tmp évite d’écraser p sur échec|Le nouveau stockage peut changer d’adresse|free(p) libère le bloc encore possédé','realloc libère toujours p sur échec|Le nouveau bloc conserve nécessairement son adresse|Il faut aussi appeler free(tmp) après free(p)',wrong=['realloc libère p sur tout échec.','Le code libère nécessairement deux fois le bloc.','realloc initialise les nouveaux éléments à zéro.'],mode='analysis'))
add(2,'strings','terminator_capacity',lambda n:case(f'char a[{n+3}]; memset(a,\'x\',sizeof a); printf("%zu",strlen(a));','Comportement indéfini','Aucun terminateur nul n’existe dans a ; strlen cherche au-delà des bornes du tableau.','Le tableau ne contient aucun nul|strlen exige une chaîne terminée|sizeof a resterait utilisable','strlen connaît la capacité du tableau|strlen ajoute le nul manquant|La sortie vaut toujours la capacité',wrong=[str(n+3),'Erreur de compilation','Segfault garanti'],mode='analysis'))
add(2,'memory','free_null',lambda n:case(f'int *p=NULL; for(int i=0;i<{n};++i)free(p); printf("ok");','ok','free(NULL) est une opération sans effet, autorisée par la bibliothèque standard.','p est un pointeur nul|free(NULL) est autorisé|Aucun bloc n’est libéré ici','free(NULL) est indéfini|La boucle alloue des blocs|Le second free est un double free sur un objet',wrong=['Comportement indéfini','Erreur de compilation','Segfault garanti']))
add(2,'pointers','one_past',lambda n:case(f'int a[{n+2}]; int *end=a+{n+2}; printf("%td",end-a);',n+2,'Former le pointeur juste après la fin est permis ; le déréférencer ne le serait pas.','end est un pointeur one-past|La soustraction est définie dans le même tableau|end ne peut pas être déréférencé','Former end est déjà indéfini|end pointe sur le dernier élément|La différence est exprimée en octets'))
add(2,'variables','unsigned_wrap',lambda n:case(f'unsigned x=0; x-={n}u; printf("%d",x==UINT_MAX-({n}u-1u));',1,'L’arithmétique unsigned est modulo UINT_MAX+1. Elle n’est pas un débordement signé indéfini.','Le type de x est unsigned|La soustraction est définie modulo la plage|UINT_MAX vient de limits.h','Tout débordement entier est indéfini|Le résultat dépend d’un int 32 bits|x devient un entier signé négatif'))
add(2,'logic','bit_set_clear',lambda n:case(f'unsigned x=0; x|=1u<<{n}; x&=~(1u<<{n}); printf("%u",x);',0,'Le premier masque positionne un bit ; le second masque, complémenté, efface ce même bit.','Les décalages portent sur un unsigned|Le masque complémenté efface le bit|Le décalage est inférieur à la largeur minimale de unsigned','Le complément ne touche qu’un bit|Le décalage est négatif|Le second masque remet tous les bits à un'))
add(2,'structures','designated_initializer',lambda n:case(f'struct P{{int x,y,z;}}; struct P p={{.y={n+2}}}; printf("%d %d",p.x,p.z);','0 0','Une initialisation désignée peut omettre des membres : les membres omis sont initialisés à zéro.','Le membre y est explicitement initialisé|Les membres omis sont mis à zéro|La syntaxe est standard en C17','L’ordre des membres doit être suivi|x et z restent indéterminés|Cette syntaxe exige C++20',wrong=[f'{n+2} {n+2}','Valeurs indéterminées','Erreur de compilation']))
add(2,'functions','function_pointer',lambda n:case(f'int (*f)(int)=twice; printf("%d",f({n+2}));',2*(n+2),'Un pointeur de fonction peut être appelé avec la syntaxe f(argument).','f pointe vers une fonction|La signature prend un int et renvoie un int|L’appel indirect est permis','f pointe vers un objet int|f doit être libéré|L’appel nécessite une conversion en void*',preamble='static int twice(int x){return 2*x;}'))
add(2,'memory','memmove_overlap',lambda n:case(f'char s[]="abcdef"; memmove(s+1,s,{n}); s[{n+1}]=0; printf("%s",s);','a'+'abcdef'[:n],'memmove permet le recouvrement des zones source et destination ; il se comporte comme avec un tampon intermédiaire.','Les zones se recouvrent|memmove accepte ce recouvrement|Le terminateur est écrit dans les bornes','memcpy serait aussi garanti ici|memmove inverse les caractères|Le tampon change de capacité',wrong=['abcdef','Comportement indéfini','Erreur de compilation']))
add(2,'strings','snprintf_truncation',lambda n:case(f'char s[4]; int r=snprintf(s,sizeof s,"%s","abcdef{n}"); printf("%d %s",r,s);','7 abc','snprintf renvoie la longueur qui aurait été écrite, hors nul, et termine le tampon de taille non nulle.','Le tampon contient trois caractères puis un nul|La valeur de retour indique une troncature|La capacité est passée explicitement','La valeur de retour vaut trois|Le nul manque après troncature|snprintf agrandit le tableau',wrong=['3 abc','4 abcd','7 abcdef']))
add(2,'arrays','multidimensional_row',lambda n:case(f'int a[2][3]={{{{1,2,3}},{{{n},7,8}}}}; printf("%d",a[1][0]);',n,'a est un tableau de deux lignes, chacune étant un tableau de trois int.','Chaque ligne contient trois int|a[1] désigne la deuxième ligne|a n’est pas un int**','Les lignes sont allouées séparément|a a le type int**|a[1][0] est hors limites'))
add(2,'files','fgetc_eof_type',lambda n:case(f'FILE *f=tmpfile(); if(!f)return 1; fputc(\'{chr(64+n)}\',f); rewind(f); int a=fgetc(f),b=fgetc(f); printf("%d %d",a==\'{chr(64+n)}\',b==EOF); fclose(f);','1 1','fgetc renvoie un int pour distinguer les valeurs d’unsigned char de EOF ; rewind repositionne et efface les indicateurs.','Le retour est stocké dans un int|rewind ramène au début|Le deuxième appel atteint la fin','Le retour doit être stocké dans char|EOF est un caractère du fichier|fgetc ajoute un nul au fichier',wrong=['1 0','0 1','Erreur de compilation']))
add(2,'algorithms','qsort_comparator',lambda n:case(f'int a[]={{{n+4},1,{n+2}}}; qsort(a,3,sizeof *a,cmp); printf("%d",a[0]);',1,'Le comparateur renvoie le signe de (a>b)-(a<b), évitant un débordement de a-b.','Le comparateur reçoit des pointeurs const void*|Le tri est en place|Le comparateur n’utilise pas une soustraction potentiellement débordante','qsort renvoie un nouveau tableau|Le comparateur doit renvoyer uniquement 0 ou 1|La fonction est réservée aux chaînes',preamble='static int cmp(const void *p,const void *q){int a=*(const int*)p,b=*(const int*)q;return (a>b)-(a<b);}'))
add(2,'functions','macro_precedence',lambda n:case(f'printf("%d",SQUARE({n}+1));',2*n+1,'La macro développe x*x sans parenthèses : n+1*n+1. La priorité de * change le résultat.','Le remplacement est textuel|Les parenthèses manquent autour des paramètres|Une fonction éviterait ce piège de priorité','La macro évalue automatiquement (n+1) au carré|Le préprocesseur connaît les types|Le résultat est indéfini',preamble='#define SQUARE(x) x*x'))
add(2,'variables','integer_promotion',lambda n:case(f'unsigned char x={n}; printf("%d",x+1);',n+1,'Les valeurs d’unsigned char tiennent dans int : x est promu en int dans cette expression.','Une promotion entière intervient|Le résultat de x+1 est ici un int|%d correspond au type du résultat','Le résultat reste unsigned char|La promotion exige un cast|%d reçoit ici un double'))
add(2,'pointers','dangling_local',lambda n:case('int *p=bad(); printf("%d",*p);','Comportement indéfini','L’objet automatique de bad cesse d’exister à son retour ; son adresse ne permet plus un accès valide.','La durée de vie de x se termine au retour|Le pointeur n’allonge pas cette durée|Une allocation dynamique changerait le contrat de libération','Retourner une adresse copie l’objet|Le déréférencement est garanti égal à la valeur initiale|Un segfault est imposé par le standard',preamble=f'static int *bad(void){{int x={n};return &x;}}',wrong=[str(n),'Erreur de syntaxe obligatoire','Segfault garanti'],mode='analysis'))
add(2,'strings','strtol_end_pointer',lambda n:case(f'char *end; long x=strtol("{n+12}kg",&end,10); printf("%ld %s",x,end);',f'{n+12} kg','strtol convertit le préfixe numérique et fait pointer end vers le premier caractère non converti.','end pointe dans la chaîne initiale|Le suffixe n’est pas consommé|La base dix est explicite','La conversion échoue dès qu’un suffixe existe|end contient une nouvelle allocation|Le suffixe est modifié',wrong=[f'{n+12} ', '0 kg','Erreur de compilation']))

# Niveau 3 : séquencement, aliasing, représentations, API et concurrence C11.
add(3,'logic','unsequenced_modifications',lambda n:case(f'int i={n}; printf("%d",i++ + i++);','Comportement indéfini','Les deux modifications de i ne sont pas séquencées l’une par rapport à l’autre. Aucun résultat arithmétique n’est garanti.','Deux modifications de i apparaissent dans une même expression|+ ne séquence pas ses opérandes|Deux instructions séparées corrigeraient ce problème','Le standard impose l’évaluation de gauche à droite|Le résultat vaut forcément 2*i+1|L’optimisation crée seule le problème',wrong=[str(2*n+1),str(2*n),'Segfault garanti'],mode='analysis'))
add(3,'memory','use_after_realloc',lambda n:case(f'int *p=malloc({n+2}*sizeof *p); if(!p)return 1; int *alias=p; int *q=realloc(p,{n+4}*sizeof *p); if(!q){{free(p);return 1;}} printf("%d",*alias); free(q);','Comportement indéfini sur le chemin de succès','Un realloc réussi invalide l’ancien pointeur et ses alias, même si l’adresse numérique semble inchangée. De plus les éléments initiaux n’ont pas été initialisés.','alias n’est pas actualisé par realloc|Le succès invalide l’ancien objet|Il faut utiliser q après le succès','alias est garanti valide si q a la même adresse|realloc met les int à zéro|Le cast de realloc réparerait alias',wrong=['Lecture valide garantie','Segfault garanti','Erreur de syntaxe obligatoire'],mode='analysis'))
add(3,'pointers','restrict_alias',lambda n:case(f'int x={n}; f(&x,&x);','Le contrat restrict est violé','Les deux pointeurs restrict servent à accéder au même objet modifié dans f. Le programme viole le contrat d’aliasing.','Les deux arguments désignent le même int|Un objet est modifié via p|restrict impose ici une contrainte au programmeur','restrict vérifie les adresses à l’exécution|Le compilateur doit signaler une erreur|restrict rend les pointeurs constants',preamble='static void f(int *restrict p,int *restrict q){*p=1;*q+=2;}',wrong=['Le compilateur doit refuser cet appel','restrict crée deux copies indépendantes','Le résultat est garanti par la syntaxe'],mode='analysis'))
add(3,'memory','effective_type_alias',lambda n:case(f'float x={n}.0f; int y=*(int*)&x; printf("%d",y);','Comportement indéfini','L’accès à un float via une lvalue int viole les règles de type effectif. Un cast de pointeur n’autorise pas cet accès.','Le stockage est celui d’un float|Le cast ne convertit pas la valeur flottante|memcpy permettrait de copier les octets vers un objet adapté','Le cast convertit x en int|Toute adresse peut être déréférencée avec tout type|La même taille des types suffit',wrong=[str(n),'Réinterprétation toujours portable','Erreur de syntaxe obligatoire'],mode='analysis'))
add(3,'memory','object_representation',lambda n:case(f'unsigned x={n+17}u; unsigned char bytes[sizeof x]; memcpy(bytes,&x,sizeof x); printf("%d",memcmp(bytes,&x,sizeof x)==0);',1,'Les octets d’une représentation d’objet peuvent être copiés et examinés avec unsigned char. Aucune hypothèse d’endianité n’est faite.','unsigned char peut examiner la représentation|memcpy ne fait pas une conversion numérique|Aucun ordre des octets n’est supposé','Le premier octet est forcément le poids faible|memcpy viole toujours le strict aliasing|Le tableau contient nécessairement quatre octets'))
add(3,'structures','padding_memcmp',lambda n:case(f'struct P{{char c;int x;}}; struct P a={{\'x\',{n}}},b={{\'x\',{n}}}; int same=memcmp(&a,&b,sizeof a)==0; (void)same;','L’égalité des membres ne garantit pas memcmp égal à zéro','Des octets de bourrage peuvent exister et ne sont pas une comparaison sémantique des membres. Comparer les membres est la solution portable.','La structure peut contenir du padding|memcmp compare aussi les octets de bourrage|Comparer les membres évite ce piège','sizeof vaut forcément sizeof(char)+sizeof(int)|memcmp compare seulement les membres|Des membres égaux imposent une représentation identique',wrong=['memcmp est forcément égal à zéro','La structure ne peut contenir aucun padding','Deux structures ne peuvent pas avoir les mêmes membres'],mode='analysis'))
add(3,'memory','allocation_overflow_guard',lambda n:case(f'size_t count=SIZE_MAX/{n+2}u+1u; size_t size={n+2}u; printf("%d",count>SIZE_MAX/size);',1,'Avant de multiplier deux size_t, tester count > SIZE_MAX/size permet de détecter un produit non représentable, si size est non nul.','size est non nul|La garde précède la multiplication|Le produit serait réduit modulo la plage de size_t','Il faut d’abord multiplier pour vérifier|size_t est signé|malloc détecte nécessairement l’intention initiale'))
add(3,'functions','macro_double_evaluation',lambda n:case(f'int x={n}; int y=MAX(x++,0); printf("%d %d",x,y);',f'{n+2} {n+1}','Le test incrémente x une première fois ; la branche vraie évalue encore x++. Le test est séquencé avant la branche choisie.','Le premier argument est évalué deux fois ici|Le test précède la branche choisie|Une fonction inline éviterait la double évaluation','Les deux incréments sont non séquencés ici|Une macro évalue chaque argument une fois|La branche fausse est exécutée',preamble='#define MAX(a,b) ((a)>(b)?(a):(b))',wrong=[f'{n+1} {n}',f'{n+1} {n+1}','Comportement indéfini']))
add(3,'logic','sizeof_side_effect',lambda n:case(f'int x={n}; size_t s=sizeof(x++); printf("%d %d",x,s==sizeof(int));',f'{n} 1','Pour cette expression de type non VLA, sizeof n’évalue pas son opérande. x n’est pas modifié.','Le type de l’opérande n’est pas un VLA|x++ n’est pas évalué|Le résultat de sizeof a le type size_t','sizeof évalue toujours son opérande|x est incrémenté|Le résultat de sizeof est toujours un int',wrong=[f'{n+1} 1',f'{n} 0','Erreur de compilation']))
add(3,'arrays','vla_bound_capture',lambda n:case(f'int n={n+2}; int a[n]; n++; printf("%zu",sizeof a/sizeof a[0]);',n+2,'La taille du VLA est déterminée à sa déclaration ; changer n ensuite ne redimensionne pas a. Ce cas suppose une implémentation C17 avec VLA.','La borne est évaluée à la déclaration|Changer n ne redimensionne pas a|sizeof a dépend de la taille capturée','Le VLA grandit quand n augmente|sizeof a est forcément constant à la compilation|La taille du tableau est une allocation malloc'))
add(3,'variables','signed_unsigned_compare',lambda n:case(f'int x=-{n}; unsigned y=1u; printf("%d",x<y);',0,'Les conversions arithmétiques usuelles convertissent ici x en unsigned ; sa valeur devient grande modulo la plage.','Les types de départ sont différents|x est converti en unsigned pour la comparaison|Le code n’exige pas une représentation signée particulière','La comparaison est signée|La conversion en unsigned est indéfinie|Un nombre écrit négativement reste toujours négatif dans cette comparaison'))
add(3,'pointers','pointer_order_unrelated',lambda n:case(f'int a[{n+1}],b[{n+2}]; printf("%d",a<b);','Comportement indéfini','L’ordre relationnel de pointeurs vers des tableaux distincts n’est pas défini par les règles C applicables ici. L’égalité de pointeurs a d’autres règles.','Les tableaux sont des objets distincts|< n’est pas une comparaison d’égalité|Une proximité sur la pile ne donne pas une garantie standard','La pile impose un ordre portable|Le compilateur doit refuser a<b|Le plus grand tableau a nécessairement la plus grande adresse',wrong=['a précède toujours b','b précède toujours a','Erreur de syntaxe obligatoire'],mode='analysis'))
add(3,'memory','malloc_alignment',lambda n:case(f'void *p=malloc({n+2}*sizeof(double)); if(!p)return 1; double *d=p; d[0]=1.5; printf("%.1f",d[0]); free(p);','1.5','malloc fournit un alignement suffisant pour les types à alignement fondamental, dont double. En C, void* se convertit implicitement en pointeur d’objet.','Aucun cast n’est requis en C|L’alignement convient à double|Le bloc est libéré après son dernier accès','Tout cast de malloc est obligatoire en C|Le bloc est forcément mal aligné|malloc initialise tout le bloc à zéro',wrong=['Erreur de compilation','Comportement indéfini','0.0']))
add(3,'structures','flexible_array_member',lambda n:case(f'size_t count={n+2}; struct S *p=malloc(sizeof *p+count*sizeof p->a[0]); if(!p)return 1; p->n=count;p->a[count-1]=7;printf("%d",p->a[count-1]);free(p);',7,'Le membre flexible est le dernier membre de la structure ; la capacité est fournie par la taille allouée supplémentaire.','Le membre flexible est en dernier|La taille allouée prévoit les éléments|L’indice count-1 est dans la capacité','sizeof la structure inclut tous les éléments demandés|Un membre flexible peut précéder un autre membre|Le tableau se redimensionne automatiquement',preamble='struct S{size_t n;int a[];};'))
add(3,'files','fread_element_count',lambda n:case(f'FILE *f=tmpfile();if(!f)return 1;unsigned char src[{n+3}];memset(src,1,sizeof src);fwrite(src,1,sizeof src,f);rewind(f);unsigned char dst[20];size_t r=fread(dst,2,{n+3},f);printf("%zu",r);fclose(f);',(n+3)//2,'fread renvoie le nombre d’éléments complets lus, pas le nombre d’octets. Un dernier élément incomplet n’est pas compté.','La taille d’un élément demandé vaut deux|Le retour compte des éléments complets|La demande dépasse le nombre d’octets disponibles','Le retour compte toujours les octets|Le tampon est agrandi automatiquement|fread renvoie EOF à la fin'))
add(3,'strings','ctype_unsigned_char',lambda n:case(f'unsigned char c=(unsigned char)(200+{n}); int r=isalpha(c); printf("%d",r!=0 || r==0);',1,'Les fonctions ctype acceptent EOF ou une valeur représentable en unsigned char. Le classement peut dépendre de la locale.','La promotion de c donne une valeur admissible|Le classement peut dépendre de la locale|Le résultat de isalpha n’est pas nécessairement 1 quand il est vrai','Un char signé négatif quelconque est toujours admissible|isalpha renvoie forcément 0 ou 1|Le classement des octets étendus est identique dans toute locale'))
add(3,'concurrency','atomic_fetch_add',lambda n:case(f'atomic_int x=ATOMIC_VAR_INIT({n});int old=atomic_fetch_add_explicit(&x,2,memory_order_relaxed);printf("%d %d",old,atomic_load(&x));',f'{n} {n+2}','fetch_add est une lecture-modification-écriture atomique et renvoie la valeur avant addition. relaxed ne synchronise pas les autres objets.','La mise à jour de x est atomique|La valeur renvoyée précède l’addition|relaxed n’impose pas un ordre inter-objets','fetch_add renvoie la nouvelle valeur|relaxed supprime l’atomicité|Toutes les opérations non atomiques sont ainsi synchronisées',preamble='#include <stdatomic.h>',wrong=[f'{n+2} {n+2}',f'{n} {n}','Erreur de compilation']))
add(3,'logic','comma_sequence',lambda n:case(f'int x={n}; int y=(x+=2,x*3);printf("%d %d",x,y);',f'{n+2} {(n+2)*3}','L’opérateur virgule séquence son opérande gauche avant le droit et produit la valeur de l’opérande droit.','L’addition précède la multiplication|Les parenthèses contiennent un opérateur virgule|L’expression produit la valeur de droite','La virgule impose ici un comportement indéfini|Le résultat de l’expression est celui de gauche|Les deux opérandes sont non séquencés',wrong=[f'{n+2} {n*3}',f'{n} {n*3}','Comportement indéfini']))
add(3,'const','string_literal_write',lambda n:case(f'char *p="mot{n}";p[0]=\'M\';','Comportement indéfini','En C, l’initialisation de char* depuis un littéral est permise, mais toute tentative de modifier le littéral a un comportement indéfini.','Le littéral a une durée de stockage statique|L’écriture tente de modifier un littéral|Un tableau char p[] aurait créé une copie modifiable','Un char* garantit que l’objet désigné est modifiable|L’initialisation est toujours une erreur syntaxique en C17|Un segfault est garanti',wrong=['Affiche la chaîne modifiée de façon garantie','Erreur de syntaxe obligatoire','Segfault garanti'],mode='analysis'))
add(3,'functions','variadic_format_mismatch',lambda n:case(f'size_t n=(size_t){n+3};printf("%d",n);','Contrat variadique violé : comportement indéfini','%d attend un int, pas un size_t. L’appel variadique ne convertit pas automatiquement le type vers celui attendu par le format ; %zu est le bon spécificateur.','Le bon spécificateur est %zu|Le format ne convertit pas size_t en int|Le type exact de size_t dépend de l’implémentation','%d accepte tout type entier|La même taille en octets suffit|Le résultat est garanti égal à n',wrong=[str(n+3),'Erreur syntaxique obligatoire','Conversion automatique en int'],mode='analysis'))
